public void RenderPage(ICanvasItemRenderer renderer)
{
	if (renderer == null)
		throw new ArgumentNullException(nameof(renderer));
	renderer.BeginPage(this);
	foreach (var canvasItem in _pageCanvasItems)
	{
		renderer.Render(canvasItem);
	}
	renderer.EndPage();
}

public class MyCanvasItem : CanvasItem
{
    public MyCanvasItem(CanvasType ctType) : base(ctType)
    {
    }
    public override CanvasItem Clone()
    {
	    return new MyCanvasItem(Type);
    }
}

public void DrawLine(float startX, float startY, float endX, float endY)
{
	CanvasItems.Add(new LineItem(startX,startY,endX,endY));
}

public void DrawRect(float startX, float startY, float endX, float endY)
{
	CanvasItems.Add(new Rect(startX,startY,endX,endY));
}

public void DrawIntersectClip(float startX, float startY, float endX, float endY)
{
	CanvasItems.Add(new IntersectClip(new RectangleF(startX,startY,endX,endY));
}

public void DrawRoundRect(float left, float top, float width, float height, float edgeWidth, float edgeHeight)
{
	CanvasItems.Add(new RoundRect(left, top, width, height, edgeWidth, edgeHeight));
}

public void AddTextInfoItem(string outputFormat, object value, CultureInfo culture, CultureInfo currencyCulture)
{
	CanvasItems.add(new TextInfoItem(outputFormat, value??0, culture, currencyCulture));
}

